async function run() {
  const lemmas1to50 = await getAll1to50Lemmas();
  console.log(`Loaded ${lemmas1to50.size} existing lemmas from Days 1-50.`);

  const verifiedStage6Vocab = {};
  const globalStage6Lemmas = new Set();

  for (let d = 51; d <= 60; d++) {
    let sourceList = [];
    if (d === 51) sourceList = rawStage6Vocab[51] || [];
    else if (d >= 52 && d <= 55) sourceList = stage6Vocab52to55[d] || [];
    else sourceList = stage6Vocab56to60[d] || [];

    if (extraPool[d]) {
      sourceList = [...sourceList, ...extraPool[d]];
    }

    const uniqueForDay = [];
    const seenInDay = new Set();

    for (const item of sourceList) {
      const norm = item.lemma.trim().toLowerCase();
      if (lemmas1to50.has(norm)) {
        continue; // strictly skip 1-50 overlap
      }
      if (globalStage6Lemmas.has(norm)) {
        continue; // strictly skip intra-stage6 duplicate
      }
      if (seenInDay.has(norm)) continue;

      seenInDay.add(norm);
      globalStage6Lemmas.add(norm);
      uniqueForDay.push(item);
    }

    verifiedStage6Vocab[d] = uniqueForDay.map((item, idx) => ({
      id: `d${d}_vocab_${String(idx + 1).padStart(3, '0')}`,
      lemma: item.lemma,
      wordForm: item.wordForm || item.lemma,
      pos: item.pos || "Noun",
      ipa: item.ipa || "/ˈwɜːd/",
      hindiIpa: item.hiIpa || item.lemma,
      syllables: item.syl || item.lemma,
      stress: item.stress || "Primary on 1st syllable",
      collocations: item.colloc || [`standard ${item.lemma}`],
      relatedForms: item.rel || [],
      register: item.reg || "Formal / Professional",
      meaningHi: item.hi,
      exampleEn: item.en,
      exampleHi: item.hiEx,
      commonLearnerError: item.err || `Avoid literal translation; use natural professional collocation.`,
      recyclingSchedule: [d, Math.min(60, d + 3), 60]
    }));

    console.log(`Day ${d}: ${verifiedStage6Vocab[d].length} pristine unique vocabulary items verified!`);
  }

  fs.writeFileSync(path.join(__dirname, 'stage6_vocabulary_verified.json'), JSON.stringify(verifiedStage6Vocab, null, 2));
  console.log(`Total unique new Stage 6 lemmas: ${globalStage6Lemmas.size}`);
  console.log('Successfully wrote stage6_vocabulary_verified.json!');
}

run();
